-- Difficulty Ratings:
--  [1] = Breeze (Vendor mounts, simple gold purchases)
--  [2] = Steady (Reputation grinds or guaranteed quest rewards)
--  [3] = Challenging (Low drop rates 1-5% or difficult achievements)
--  [4] = Extremity (Ultra-low drop rates <1%, world bosses, or long meta-achievements)
--  [5] = Insanity (0.01% drops, discontinued/legacy, or Glad-level PvP)

--  Categories
--   [0] = "Unobtainable"
