   ["tips"] = "Dusklight Razorwing. \n\n1. Source: Hidden Quest Reward (Duskwing Matriarch). \n2. Method: Farm 'Devourer' mobs in North-West Korthia (Mauler's Outlook) /way 35.0 46.0. They drop 'Lost Razorwing Eggs' (Cap: 2 per day). \n3. Turn-in: Take 10 eggs to the Razorwing Nest at /way 25.5 51.1. \n4. Note: Highly recommended to save all 10 eggs in your bags and turn them in at once. Blizzard has reset partial quest progress during major patch transitions in the past.",
