   ["mountID"] = 1511,
   ["name"] = "Maelie, the Wanderer",
   ["tips"] = "Maelie, the Wanderer. \n\n1. Source: Korthia Daily Interaction. \n2. Method: You must find Maelie 6 times. She spawns in one of several random locations around Korthia each day. \n3. Requirement: Talk to Tiny Bell in Keeper's Respite first to start the search. Once you find Maelie 6 times (on 6 different days), return to Tiny Bell for the mount. \n4. Tip: Use a macro '/target Maelie' while riding around to find her easily.",
