{
   ["mountID"] = 1545,
   ["name"] = "Divine Kiss of Ohn'ahra (Eagle)",
   ["tips"] = "Divine Kiss of Ohn'ahra (Eagle). \n\n1. Source: Secret Questline in the Ohn'ahran Plains. \n2. Requirement: Renown 25 with Maruuk Centaur. \n3. Process: You must obtain 3x 'Stolen Breath of Ohn'ahra' (from the Nokhud Offensive dungeon) and an 'Exultant Incense'. \n4. How-to: Speak to Godmother Binaka at /way 22.0 51.0 while having the items. \n5. Transformation: This is technically a transformation mount—you *become* the eagle.",
   ["author"] = "AI",
   ["difficulty"] = 4, -- Challenging (Renown + Secret quest)
   ["category"] = 5,
   ["expansion"] = 9,
},
{
   ["mountID"] = 1546,
   ["name"] = "Iskaara Trader's Ottuk",
   ["tips"] = "Iskaara Trader's Ottuk. \n\n1. Source: Barter NPC 'Tattamus' in Iskaara (/way 14.0 49.3). \n2. Cost: 1x Terros's Captive Core (from Vault of the Incarnates) and 1x Eye of the Vengeful Hurricane (from Dathea). \n3. Strategy: In 2026, you can easily solo the first few bosses of Vault on Normal/Heroic to get these items. \n4. Note: This is one of the few Ottuks that wears traditional Tuskarr fishing gear.",
   ["author"] = "AI",
   ["difficulty"] = 3, -- Medium (Raid item farming)
   ["category"] = 1,
   ["expansion"] = 9,
},
{
   ["mountID"] = 1547,
    ["name"] = "Goldplate Bufonid",
    ["tips"] = "Goldplate Bufonid. \n\n1. Schematic: Dropped by 'Accelerated Bufonid' elites. Best farm is /way 51.0 74.3 (near the waterfalls) or the elite island to the Northeast. \n2. Material: 1x Bauble of Pure Innovation. Guaranteed purchase from the Enlightened Quartermaster (Revered) or found in 'Exile's Hollow'. \n3. Components: 1x Bufonid Lattice, 400x Genesis Mote. \n4. Note: This is the shiny golden version of the Zereth Mortis frog.",
    ["author"] = "AI",
    ["difficulty"] = 3,
