    ["subcategory"] = 64,

},
{
   ["mountID"] = 1549,
   ["name"] = "Shimmering Aurelid (Jellyfish)",
   ["tips"] = "Shimmering Aurelid (Jellyfish). \n\n1. Source: Achievement 'Glory of the Sepulcher Raider'. \n2. Task: Complete all 11 encounter achievements inside the Sepulcher of the First Ones raid. \n3. Strategy: In 2026, this is easily soloable on most classes. Some achievements like 'Four Rings, One Ring' may still require a small group for positioning. \n4. Note: Does not require the Protoform Forge; it is a direct achievement reward.",
   ["author"] = "AI",
   ["difficulty"] = 4, -- Challenging (Solo raid mechanics)
   ["category"] = 2,
   ["expansion"] = 8,
},
{
   ["mountID"] = 1550,
    ["name"] = "Depthstalker",
    ["tips"] = "Depthstalker. \n\n1. Source: Trading Post (Special Reward). \n2. Method: Originally the October 2024 monthly reward. In 2026, keep an eye on the Trading Post rotation (costs 600 Trader's Tender). \n3. Quirk: This is a Flying mount that actually has a custom 'swimming' animation in the air. \n4. Note: No crafting required.",
