    ["subcategory"] = 12,

},
{
   ["mountID"] = 1551,
   ["name"] = "Cryptic Aurelid",
   ["tips"] = "Cryptic Aurelid. \n\n1. Source: Achievement 'From A to Zereth'. \n2. Task: This is the Meta-Achievement for the entire Zereth Mortis zone. \n3. Requirements: Explore ZM, complete 'Secrets of the First Ones",
   ["author"] = "AI",
   ["difficulty"] = 5, -- Very Hard (Long-term meta grind)
   ["category"] = 2,
   ["expansion"] = 8,
},
{
   ["mountID"] = 1552,
    ["name"] = "Carcinized Zerethsteed",
    ["tips"] = "Carcinized Zerethsteed. \n\n1. Source: This was originally the 'Ahead of the Curve' reward for defeating The Jailer on Heroic before the Dragonflight pre-patch. \n2. Current Status: In 2026, it is officially listed as 'No longer obtainable.' \n3. Quest: The 'Leading Motives' quest you see was the turn-in for the 'Almanac's Echo' dropped by the Heroic Jailer. \n4. Note: If you have the quest in your log but never finished it, you can still turn it in to Firim in Exile's Hollow to get the mount. Otherwise, it is currently unavailable.",
    ["author"] = "AI",
    ["difficulty"] = 5,
    ["category"] = 2,
    ["expansion"] = -1,
    ["subcategory"] = 16,
    ["unobtainable"] = 1,


},
{
   ["mountID"] = 1553,
   ["name"] = "Liberated Slyvern",
   ["tips"] = "Liberated Slyvern. \n\n1. Source: Drop from the rare elite 'Breezebiter' in the Azure Span (/way 37.6 63.5). \n2. Farming: Breezebiter has a long respawn timer (1-2 hours) and a low drop rate (approx. 2-3%). \n3. Strategy: He flies in a small circle near the mountainside. If you have the 'TomCat's Tours' addon, it will track his spawn specifically. \n4. Note: Unlike the Korthia version, this is the blue/white Dragonflight variant.",
   ["author"] = "AI",
   ["difficulty"] = 4, -- Challenging (Annoying spawn timer/Low drop)
   ["category"] = 3,
   ["expansion"] = 9,
},
{
   ["mountID"] = 1556,
   ["name"] = "Tangled Dreamweaver",
   ["tips"] = "Tangled Dreamweaver. \n\n1. Source: Dragonflight Heroic/Epic Edition Purchase. \n2. Current Status: In 2026, it is available only via the Battle.net Shop if you upgrade your Dragonflight base license to the Heroic/Epic edition. \n3. Quirk: This mount changes colors based on the environment (Green in nature, blue in water/cold areas). \n4. Note: It is a 'Dreamrunner' model similar to the unicorns of Ardenweald.",
   ["author"] = "AI",
   ["difficulty"] = 1, -- Very Easy (Store/Upgrade)
   ["category"] = 10,
   ["expansion"] = 9,
},
{
   ["mountID"] = 1563,
   ["name"] = "Highland Drake",
   ["tips"] = "Highland Drake. \n\n1. Source: Dragonflight Main Campaign. \n2. How-to: Automatically rewarded after completing the 'Azure Spanners' chapter in the Azure Span (Quest: 'Calling the Blue Dragons'). \n3. Customization: This is a Dynamic Flight mount. You can change its appearance at any Rostrum of Transformation using 'Manuscripts' found throughout the world. \n4. Note: This is your primary blue dragonriding mount.",
   ["author"] = "AI",
   ["difficulty"] = 1, -- Very Easy (Quest Reward)
   ["category"] = 5,
   ["expansion"] = 9,
},

{
   ["mountID"] = 1564,
   ["name"] = "Colossal Soulshredder Mawrat",
   ["tips"] = "Colossal Soulshredder Mawrat. \n\n1. Source: Achievement 'The Jailer's Gauntlet: Layer 1'. \n2. Location: Torghast, Tower of the Damned. Enter the portal for 'The Jailer's Gauntlet'. \n3. Strategy: This is the entry-level layer. Just focus on high-burst damage powers to delete the bosses before they ramp up. \n4. Note: This version is the pale, grey-skinned variant.",
   ["author"] = "AI",
   ["difficulty"] = 2, -- Easy (Soloable in legacy gear)
   ["category"] = 2,
   ["expansion"] = 8,
},

{
   ["mountID"] = 1565,
   ["name"] = "Colossal Umbrahide Mawrat",
   ["tips"] = "Colossal Umbrahide Mawrat. \n\n1. Source: Achievement 'The Jailer's Gauntlet: Layer 2'. \n2. Location: Torghast, Tower of the Damned. \n3. Strategy: Bosses start having more health here. Pick defensive anima powers early, then stack 'increased damage taken by enemies' powers. \n4. Note: This is the dark-skinned, shadowy variant.",
   ["author"] = "AI",
   ["difficulty"] = 2, -- Easy
   ["category"] = 2,
   ["expansion"] = 8,
},

{
   ["mountID"] = 1566,
   ["name"] = "Colossal Ebonclaw Mawrat",
   ["tips"] = "Colossal Ebonclaw Mawrat. \n\n1. Source: Achievement 'The Jailer's Gauntlet: Layer 4'. \n2. Requirement: You must clear Layers 1, 2, and 3 first. \n3. Strategy: At Layer 4, the bosses hit significantly harder. If you are struggling, use a class with high sustain (Blood DK, Prot Paladin) or high mobility to avoid the telegraphs. \n4. Note: This is the 'armored' variant with the dark plating. Often confused with the Carcinized Zerethsteed due to the similar Achievement tier.",
   ["author"] = "AI",
   ["difficulty"] = 3, -- Medium (Requires a full run of the first 4 layers)
   ["category"] = 2,
   ["expansion"] = 8,
},
{
   ["mountID"] = 1568,
    ["name"] = "Lightforged Ruinstrider",
    ["tips"] = "Lightforged Ruinstrider. \n\n1. Source: Lightforged Draenei Paladin Class Mount. \n2. How-to: Automatically granted when you reach Level 10 on a Lightforged Draenei Paladin. \n3. Account-Wide: Once unlocked, it is usable by any Paladin on your account. \n4. Appearance: An armored Talbuk with glowing yellow naaru-tech plating.",
