{
   ["mountID"] = 2262,
   ["name"] = "Harmonious Salutations Bear",
   ["tips"] = "Harmonious Salutations Bear. \n\n1. Source: China-only Battle.net promotion. \n2. Method: This mount was given free to eligible returning World of Warcraft players in China when the game returned to the region in 2024. \n3. Note: This promotion was never made available worldwide. The mount has a blue Alliance flag or red Horde flag and is essentially the Chinese promotional version of the Big Blizzard Bear. Do not confuse it with Harmonious Greetings Bear from Classic.",
   ["author"] = "AI",
   ["difficulty"] = 5,
   ["category"] = 10, -- Blizzard Store / Promotions
   ["expansion"] = 10, -- The War Within
},

{
   ["mountID"] = 2265,
   ["name"] = "Trader's Gilded Brutosaur",
   ["tips"] = "Trader's Gilded Brutosaur. \n\n1. Source: Battle.net Shop. \n2. Method: Purchase the mount from the in-game shop when it is offered. It costs $90 USD and includes both Auction House and Mailbox functionality through the NPCs riding on the mount. \n3. Note: This is a limited-time shop mount rather than a permanently available store item. It was originally sold during the 20th Anniversary and returned for a second run from November 17, 2025 through January 5, 2026. It is currently unavailable, so keep an eye on future anniversary or special shop rotations if you are missing it.",
   ["author"] = "AI",
   ["difficulty"] = 5,
   ["category"] = 10, -- Blizzard Store / Promotions
   ["expansion"] = 10, -- The War Within
},
{
   ["mountID"] = 2778,
    ["name"] = "Ancestral War Bear",
    ["tips"] = "Ancestral War Bear. \n\n1. Source: Treasure 'Honored Warrior's Cache' in Zul'Aman. \n2. Method: First interact with the cache at [button=\"/way #2437 46.8 81.9 Honored Warrior's Cache\"]. This activates four Honored Warrior's Urns around Zul'Aman. Interact with each urn to summon one of the Amani Loa's Chosen, defeat it, and loot its token. Return to the cache with all four tokens to obtain the mount. \n3. Urn Locations:\n  1. Nalorakk's Chosen [button=\"/way #2437 32.7 83.5 Nalorakk's Chosen \"]\n  2. Halazzi's Chosen [button=\"/way #2437 34.5 33.5 Halazzi's Chosen \"]\n  3. Jan'alai's Chosen [button=\"/way #2437 54.8 22.4 Jan'alai's Chosen \"]\n  4. Akil'zon's Chosen [button=\"/way #2437 51.6 84.9 Akil'zon's Chosen\"]\n4. Note: You must interact with the Honored Warrior's Cache first or the urns may not become available. The four summoned Chosen drop Bear Tooth, Lynx Claw, Dragonhawk Feather, and Eagle Talon respectively. The enemies are level 90, so lower-level characters may want help.",
    ["author"] = "Dev",
    ["difficulty"] = 2,
    ["category"] = 3,
    ["expansion"] = 11,
    ["subcategory"] = 28,

},
{
   ["mountID"] = 2272,
   ["name"] = "Crimson Armored Growler",
   ["tips"] = "Crimson Armored Growler. \n\n1. Source: Vendor Rocco Razzboom in The Scrapshop, Undermine. \n2. Requirement: Reach Exalted with the Bilgewater Cartel and purchase the mount for 8,125 Resonance Crystals. \n3. Note: Rocco is located just west of the Demolition Dome in the north of Undermine. The reputation grind can be done through the normal Cartels of Undermine activities. Save your Resonance Crystals for the mount if this is one of your targets, as several other cartel rewards also use the same currency.",
   ["author"] = "AI",
   ["difficulty"] = 2,
   ["category"] = 4, -- Reputation
   ["expansion"] = 10, -- The War Within
},
{
   ["mountID"] = 2274,
    ["name"] = "Blackwater Bonecrusher",
    ["tips"] = "Blackwater Bonecrusher. \n\n1. Source: 'Blackwater's Trove' from the Blackwater Cartel. \n2. Requirement: Reach Exalted with the Blackwater Cartel to unlock the cartel's Paragon-style reputation rewards, then keep earning reputation to receive additional Blackwater's Troves. The mount has a chance to be inside these troves. \n3. Note: This is not a guaranteed Exalted reward. Reaching Exalted only unlocks the Paragon/Trove stage; you then need to continue earning reputation for additional troves and rely on RNG for the mount. The mount is therefore a considerably longer farm than the direct cartel vendor mounts.",
    ["author"] = "AI",
    ["difficulty"] = 4,
    ["category"] = 4,
    ["expansion"] = 10,
    ["subcategory"] = 60,

},
{
   ["mountID"] = 2786,
    ["name"] = "Hexed Vilefeather Eagle",
    ["tips"] = "Hexed Vilefeather Eagle. \n\n1. Source: Treasure 'Abandoned Ritual Skull' in the Maisara Deeps of Zul'Aman. \n2. Method: Farm 1,000 Vile Essence from the elite trolls around the Maisara Caverns, then use the currency to open the Abandoned Ritual Skull [button=\"/way #2437 44.7 44.1 Abandoned Ritual Skull\"]. \n3. Note: Vile Essence has a low drop rate, making this a lengthy farm. Do not farm it solo unless you have to—join or create a Vile Essence farming group to dramatically improve the kill rate. The highest mob density is around the entrance to Maisara Caverns. If you have the 'Send Dem Home' quest active, Shadra's Gift provides the Reciprocal Power buff, which improves your ability to farm the elite mobs.",
    ["author"] = "AI (Corrected by Dev)",
    ["difficulty"] = 3,
    ["category"] = 3,
    ["expansion"] = 11,
    ["subcategory"] = 28,

},
{
   ["mountID"] = 2276,
   ["name"] = "Darkfuse Chompactor",
   ["tips"] = "Darkfuse Chompactor. \n\n1. Source: Vendor Ando the Gat inside the Liberation of Undermine raid. \n2. Requirement: Reach Renown Rank 17 with the Gallagio Loyalty Rewards Club, then purchase the mount from Ando for 500 gold. \n3. Note: Gallagio Loyalty reputation comes from bosses and lieutenants inside the raid. You do not need Mythic difficulty—the reputation is awarded from every difficulty, including Raid Finder. If you are specifically farming renown, clearing the final wings of LFR is a convenient way to target multiple bosses quickly.",
   ["author"] = "AI",
   ["difficulty"] = 2,
   ["category"] = 4, -- Reputation
   ["expansion"] = 10, -- The War Within
},

{
   ["mountID"] = 2277,
   ["name"] = "Violet Armored Growler",
   ["tips"] = "Violet Armored Growler. \n\n1. Source: Vendor Smaks Topskimmer in the Incontinental Hotel, Undermine. \n2. Requirement: Reach Renown Rank 15 with The Cartels of Undermine and purchase the mount for 8,125 Resonance Crystals. \n3. Note: Smaks is inside the Incontinental Hotel at roughly /way #2346 43.8 50.8. Cartels of Undermine renown is earned from the various cartel activities in Undermine. The mount is a direct purchase once Rank 15 is reached, so there is no additional RNG involved.",
   ["author"] = "AI",
   ["difficulty"] = 2,
   ["category"] = 4, -- Reputation
   ["expansion"] = 10, -- The War Within
},

{
   ["mountID"] = 2278,
   ["name"] = "Flarendo the Furious",
   ["tips"] = "Flarendo the Furious. \n\n1. Source: Vendor Ando the Gat inside the Liberation of Undermine raid. \n2. Requirement: Reach Renown Rank 20 with the Gallagio Loyalty Rewards Club, then purchase the mount from Ando the Gat. \n3. Note: Gallagio Loyalty reputation is earned exclusively through the Liberation of Undermine raid. Any difficulty works, including Raid Finder. The four bosses Vexie, Rik Reverb, Stix Bunkjunker, and Chrome King Gallywix together provide a full 2,500 reputation level, making the final two LFR wings a convenient repeatable route for renown farming. Ando is on the second floor of the Incontinental Hotel inside the raid entrance.",
   ["author"] = "AI",
   ["difficulty"] = 3,
   ["category"] = 4, -- Reputation
   ["expansion"] = 10, -- The War Within
},

{
   ["mountID"] = 2279,
