   ["tips"] = "Thunderdrum Misfire. \n\n1. Source: Vendor Ando the Gat inside the Liberation of Undermine raid. \n2. Requirement: Reach Renown Rank 8 with the Gallagio Loyalty Rewards Club, then purchase the mount for 500 gold. \n3. Note: Gallagio Loyalty reputation comes from defeating bosses and lieutenants in the raid, and the reputation is the same regardless of difficulty. Raid Finder is therefore perfectly fine if you only need the renown. Ando the Gat is on the second floor of the Incontinental Hotel inside the raid entrance.",
