{
   ["mountID"] = 2280,
   ["name"] = "The Topskimmer Special",
   ["author"] = "AI",
   ["tips"] = "The Topskimmer Special. \n\n1. Source: Vendor Smaks Topskimmer in the Incontinental Hotel, Undermine. \n2. Requirement: Reach Renown Rank 19 with The Cartels of Undermine and purchase the mount for 11,375 Resonance Crystals. \n3. Note: Smaks is located at /way #2346 43.8 50.8. The Cartels of Undermine renown is earned through the various Undermine activities, while Resonance Crystals come from quests, world content and other activities in the zone. Make sure you are working on the shared Cartels renown rather than one of the individual cartel reputations.",
   ["difficulty"] = 2,
