{
   ["mountID"] = 3062,
    ["name"] = "Venomous Coiler",
    ["tips"] = "Venomous Coiler. \n\n1. Source: Achievement 'Assault the Vault'. \n2. Method: Complete all 10 achievements that make up the Assault the Vault meta-achievement in the Vaults of Atal'Utek. \n3. Note: The requirements cover patrols, strikes, incursions, Ancient Foes, funerary inscriptions, named elites, event objectives, rituals, and the Altar of Corrosion.",
