    ["expansion"] = 11,
},
{
   ["mountID"] = 3053,
    ["name"] = "Emerald Skyfang",
    ["tips"] = "Emerald Skyfang. \n\n1. Source: Achievement 'Pro Poison Patroller'. \n2. Method: Complete 250 patrols within the Vaults of Atal'Utek. \n3. Note: Patrols are activities found throughout the Vaults of Atal'Utek. Fishing up 'Sulfurous Sludgefish' from Bubbling Beryl pools, or purchased from Auction House. Using this item gives you a buff that lets you avoid hostile NPCs and safely complete the patrol objectives.",
