{
   ["mountID"] = 2607,
   ["name"] = "Ashes of Belo'ren",
   ["tips"] = "Ashes of Belo'ren. \n\n1. Source: Mythic Raid 'March on Quel'Danas'. \n2. Method: Defeat Midnight Falls, the final boss, on Mythic difficulty. Three mounts drop from each Mythic kill while the current expansion's reward system is active. \n3. Note: This is not a personal guaranteed drop for every raider—the three mounts are distributed from the Mythic kill. Run Mythic with a group that understands the mount allocation rules and be prepared for multiple kills.",
   ["author"] = "AI",
   ["difficulty"] = 5,
   ["category"] = 6, -- Raid
   ["expansion"] = 11, -- Midnight
},

{
   ["mountID"] = 2950,
   ["name"] = "Luminous Sporeglider",
   ["tips"] = "Luminous Sporeglider. \n\n1. Source: Raid 'Sporefall' - Rotmire. \n2. Method: Defeat Rotmire on any difficulty and loot a Delicious Sporesnack. You need 4 Sporesnacks to create the mount. \n3. Note: Only one Sporesnack can be obtained per account each week, so you need to defeat Rotmire across 4 weekly resets. There is currently no catch-up mechanic, making it important not to miss your weekly kill. LFR is enough, so this is an easy weekly pickup if you are only after the mount.",
   ["author"] = "AI",
   ["difficulty"] = 2,
   ["category"] = 6, -- Raid
   ["expansion"] = 11, -- Midnight
},

{
   ["mountID"] = 3030,
   ["name"] = "Primeval Skyfriend",
   ["tips"] = "Primeval Skyfriend. \n\n1. Source: Mythic Raid 'The Venomous Abyss' - Ula'tek. \n2. Method: Defeat Ula'tek on Mythic difficulty. Three Primeval Skyfriend mounts drop from each Mythic kill. \n3. Note: The three mounts are raid drops to be distributed among the group, so a Mythic kill does not guarantee one to every raider. Ula'tek is the final boss of The Venomous Abyss, making this a Mythic-only farm.",
   ["author"] = "AI",
   ["difficulty"] = 5,
   ["category"] = 6, -- Raid
   ["expansion"] = 11, -- Midnight
},

