   ["mountID"] = 2817,
   ["name"] = "Lucent Hawkstrider",
   ["tips"] = "Lucent Hawkstrider. \n\n1. Source: Midnight Dungeon 'Magisters' Terrace' - Degentrius. \n2. Method: Defeat Degentrius on Mythic difficulty, or obtain a Magisters' Terrace Challenger's Cache from Mythic+. \n3. Note: This mount is only available while Magisters' Terrace is in the seasonal dungeon pool. It was unavailable during Season 2, but Magisters' Terrace is confirmed to return in Midnight Season 3, making this mount available again then.",
   ["author"] = "AI",
   ["difficulty"] = 4,
   ["category"] = 7, -- Dungeon
   ["expansion"] = 11, -- Midnight
},

{
   ["mountID"] = 3058,
