    ["tips"] = "Arcanovoid Construct. \n\n1. Source: Delve Achievement 'Let Me Solo Him: Nullaeus'. \n2. Method: Defeat the Midnight Season 1 Nemesis, Nullaeus, completely solo on the required Nemesis difficulty. \n3. Note: This was a Season 1-only reward and became unobtainable when Season 2 began. Unlike many seasonal mounts, this one does not currently have a standard post-season farm method, so it should be treated as a limited-time mount.",
