--# 11-3 Midnight Rares #--

{
   ["mountID"] = 3031,
   ["name"] = "Hexflame Reaver",
   ["tips"] = "Hexflame Reaver. \n\n1. Source: Prey Boss 'Ral'kala' on The Coiled Isle. \n2. Method: Unlock Curse of the Isle, collect Ossified Relics, and use them at a Haunted Brazier to summon Ral'kala during Nightmare Prey. Contribute at least 1 Ossified Relic to the summon and tag Ral'kala to become eligible for the loot, including the mount. \n3. Note: A full summon requires 100 Ossified Relics, but you only need to contribute 1 to be eligible once Ral'kala spawns. This makes joining an existing group extremely useful—you can spend only 1 relic per kill instead of supplying the whole summon yourself. Ral'kala is repeatable, so there is no daily kill limit preventing you from farming him repeatedly. The mount is pushed as a reward rather than requiring you to loot a corpse, but you still need to be alive/eligible when he dies.",
   ["author"] = "AI",
   ["difficulty"] = 3,
   ["category"] = 3, -- Rare
   ["expansion"] = 11, -- Midnight
},
