    ["tips"] = "Sanguine Harrower. \n\n1. Source: Rare mob drop in Voidstorm. \n2. Method: Rare drop (~1% chance) from elite rare enemies within the Voidstorm zone. \n3. Strategy: Efficiently cycle through rare spawns using Group Finder to hop between different world shards. Daily lockout per character.",
