{
   ["mountID"] = 3051,
    ["name"] = "Topaz Skyfang",
    ["tips"] = "Topaz Skyfang. \n\n1. Source: The Coiled Isle Rare Creatures. \n2. Method: Kill the rare creatures found throughout The Coiled Isle for a chance at the mount. The mount can drop from any of the zone's rares. \n3. Note: The reported drop chance is around 0.3%, so expect a serious grind. Rares generally respawn every ~10 minutes, making it worthwhile to make a circuit of the island rather than camping a single spawn. Several rares can also appear as part of the rotating Cursed Surge events. Use a rare-tracking addon to keep up with active spawns.",
    ["author"] = "AI",
