{
   ["mountID"] = 3061,
    ["name"] = "Ruby Writhe",
    ["tips"] = "Ruby Writhe. \n\n1. Source: The Coiled Isle Rare Creatures. \n2. Method: Kill the rare creatures found throughout The Coiled Isle for a chance at the mount. The mount can drop from any of the zone's rares. \n3. Note: The reported drop chance is around 0.3%, so this is one of the more brutal Midnight rare-mount farms. Rares generally respawn every ~10 minutes, so running a circuit of the island and killing every available rare is more efficient than waiting at one location. The rotating Cursed Surge events can also provide rare bosses to kill.",
    ["author"] = "AI",
