    ["tips"] = "Frenzied Shredclaw. \n\n1. Source: Slayer's Duellum Reputation Quartermaster (Thraxadar). \n2. Requirement: Exalted with the 'Slayer's Duellum' faction. \n3. Cost: 6,000 Voidlight Marl. \n4. Note: This is an Exalted-gated reputation mount. You will gain natural progress through PvP world content in the expansion.",
    ["author"] = "AI",
