{
   ["mountID"] = 2764,
    ["name"] = "Duskbrute Harrower",
    ["tips"] = "Duskbrute Harrower. \n\n1. Source: Slayer's Duellum Trove (Paragon Cache). \n2. Method: Earn 10,000 rep after Exalted to receive a Trove. \n3. Note: Estimated 10% drop chance. RNG-gated grind.",
    ["author"] = "AI",
    ["difficulty"] = 4,
    ["category"] = 4,
    ["expansion"] = 11,
},
{
   ["mountID"] = 3019,
    ["name"] = "Sea-Dwelling Isle Serpent",
    ["tips"] = "Sea-Dwelling Isle Serpent. \n\n1. Source: Reputation Vendor - Second Mate Sluggs, The Coiled Isle. \n2. Requirement: Reach Bloodsworn Crew (Rank 5/5) with Captain Tokka's Crew and purchase the mount for 2,500 Coiled Filament. \n3. Note: After reaching Bloodsworn Crew, buy and equip The Coiled Huntress. Successful fishing attempts on The Coiled Isle build Venom on the rod; speak to Seasage Polo at Tokka's Folly to cleanse the Venom into Coiled Filament. This means you are effectively farming 2,500 successful fishing casts for the mount. Players have also reported that Venom can be farmed throughout Midnight rather than only on The Coiled Isle, allowing you to combine the grind with other fishing objectives. If you want to speed up the final stretch, community reports describe buying Beached Asteroid and converting it into Bulbous Benthos, which can then be used to generate Venom more quickly.",
    ["author"] = "AI",
    ["difficulty"] = 2,
    ["category"] = 4,
    ["expansion"] = 11,
},

--# 11-5 Midnight Quests #--

{
   ["mountID"] = 2785,
   ["name"] = "Relinquished Scarlet Charger",
   ["tips"] = "Relinquished Scarlet Charger. \n\n1. Source: Arator's Journey Campaign (Patch 12.0.1). \n2. Method: Rewarded automatically upon completing the 'Relinquishing Relics' story questline in Quel'Thalas. \n3. Note: An HD remake of the iconic Paladin charger skeleton, available to all classes.",
   ["author"] = "AI",
   ["difficulty"] = 1,
   ["category"] = 5, -- Quest
   ["expansion"] = 11, -- Midnight
},
{
   ["mountID"] = 2749,
    ["name"] = "Echo of Aln'sharan",
    ["tips"] = "Echo of Aln'sharan. \n\n1. Source: Ritual in Harandar. \n2. Method: Complete the 'Legend of Aln'sharan' quest chain starting with Kuri at /way 67.7 27.5 (Ha-Kuai). \n3. Farming: Collect 500 'Mysterious Skyshards' (Zone-wide drop: mobs, rares, delves, dungeons). \n4. Ritual: Return to the pool at /way 66.2 25.5 and throw in all 500 shards with the extra action button. \n5. Unlock: After the ritual buff, fly along the perimeter of Harandar to find Aln'sharan in the sky. Land on the serpent, dismount, and click to interact/loot.",
    ["author"] = "AI",
    ["difficulty"] = 4,
    ["category"] = 5,
    ["expansion"] = 11,
},
{
   ["mountID"] = 2818,
   ["name"] = "Emerald Hawkstrider",
   ["tips"] = "Emerald Hawkstrider. \n\n1. Source: Quest 'The Battle of the Bridge'. \n2. Method: Complete the Battle of the Bridge campaign scenario in Silvermoon City. The mount is awarded directly upon completion alongside the Emerald Hatchling. \n3. Note: This is part of the Midnight max-level campaign and is obtained during the March on Quel'Danas storyline. The scenario is mostly combat and story content, so there is no mount-specific grind or drop chance to worry about.",
   ["author"] = "AI",
   ["difficulty"] = 2,
   ["category"] = 5, -- Quest
   ["expansion"] = 11, -- Midnight
},

{
   ["mountID"] = 2754,
   ["name"] = "Peridot Dragonhawk",
   ["tips"] = "Peridot Dragonhawk. \n\n1. Source: World Quest 'From Darkness, Light'. \n2. Method: Complete the world quest on the Isle of Quel'Danas and perform the ritual with Lady Liadrin to cleanse the Darkwell. The mount is awarded directly when the quest is completed. \n3. Note: The quest is part of the Silvermoon/Quel'Danas storyline and is not a random mount drop. If the quest initially appears bugged and the NPCs are missing, player reports have found that flying through the opening in the dome rather than using the main entrance can place you directly where the quest NPCs are located.",
   ["author"] = "AI",
   ["difficulty"] = 2,
   ["category"] = 5, -- Quest
   ["expansion"] = 11, -- Midnight
},

{
   ["mountID"] = 2611,
   ["name"] = "Dusk Grimlynx",
   ["tips"] = "Dusk Grimlynx. \n\n1. Source: Quest 'History Lesson' in the Legacy of the Amani storyline. \n2. Method: Complete 'Hagar's Invitation' and then 'History Lesson' in Harandar. During History Lesson you simply need to speak with the six delegates before returning to Orweyna; the mount is awarded directly from the quest. \n3. Note: The entire quest takes place in the Den in Harandar and the actual mount quest is very quick. If you cannot find the breadcrumb, 'The Preparations Are Complete' can be started through the Adventure Guide's Suggested Content section under Legacy of the Amani. The storyline was added in Patch 12.0.7.",
   ["author"] = "AI",
   ["difficulty"] = 2,
   ["category"] = 5, -- Quest
   ["expansion"] = 11, -- Midnight
},

{
   ["mountID"] = 2980,
   ["name"] = "Spirit of Tok'jara",
   ["tips"] = "Spirit of Tok'jara. \n\n1. Source: Quest 'The Innocent Essence' in the Vaults of Atal'Utek. \n2. Method: Reach Renown 10 with Zul'jarra's Forces to unlock the special daily quest chain from Du'gal. Complete one quest per day for 6 days; 'The Innocent Essence' is the sixth quest and awards the mount. \n3. Note: The quests rotate through Ancestral Gems, Dark Charms, A Balance Paid in Blood, Wading In, Cursed Existence, and finally The Innocent Essence. The quests are fairly simple but take place inside the Vaults of Atal'Utek, and several recommend a group of three. Most can be completed in a raid group, making grouping a good way to speed up the more combat-heavy objectives.",
   ["author"] = "AI",
   ["difficulty"] = 2,
   ["category"] = 5, -- Quest
   ["expansion"] = 11, -- Midnight
},

