},{
   ["mountID"] = 2840,
   ["name"] = "Silvermoon's Arcane Defender",
   ["tips"] = "Silvermoon's Arcane Defender. \n\n1. Source: Vendor 'Telemancer Astrandis' at Delver's Headquarters (The Bazaar, Silvermoon City). \n2. Cost: 10 Voidlight Marl. \n3. Requirement: Must reach Rank 5 of the Midnight seasonal Delver's Journey. \n4. Strategy: Advance your seasonal track by running Bountiful Delves daily and completing the weekly Delve progression quests.",
   ["author"] = "AI",
