   ["category"] = 1, -- Vendor
   ["expansion"] = 11, -- Midnight
},
{
   ["mountID"] = 2841,
   ["name"] = "Elven Arcane Guardian",
   ["tips"] = "Elven Arcane Guardian. \n\n1. Source: Vendor 'Naleidea Rivergleam' at Delver's Headquarters (The Bazaar, Silvermoon City). \n2. Cost: 10,000 Undercoin. \n3. Strategy: Gather Undercoins predictably by completing weekly Bountiful Delves at Tier 8 or higher throughout the expansion zones. \n4. Note: A noble magically animated construct forged with distinct Sin'dorei armor plating.",
   ["author"] = "AI",
   ["difficulty"] = 4,
   ["category"] = 1, -- Vendor
   ["expansion"] = 11, -- Midnight
},
{
   ["mountID"] = 2913,
   ["name"] = "Vivid Chloroceros",
   ["tips"] = "Vivid Chloroceros. \n\n1. Source: Vendor (Mothkeeper Wew'tam in The Den, Harandar). \n2. Cost: 10x Luminous Dust. \n3. Requirement: You must first capture 50 'Glowing Moths' throughout Harandar to unlock the vendor's stock. \n4. Note: Progress is account-wide; additional moths are required for the 'Elder Glowmite' mount.",
   ["author"] = "AI",
   ["difficulty"] = 2,
   ["category"] = 1,
   ["expansion"] = 11, -- Midnight
},
{
   ["mountID"] = 2161,
   ["name"] = "Elder Glowmite",
   ["tips"] = "Elder Glowmite. \n\n1. Source: Mothkeeper Wew'tam (Harandar, /way 49.3 54.36). \n2. Requirement: Purchase for 10 Luminous Dust. \n3. Gating: Requires Renown 9 with Hara'ti to unlock the 3rd set of moths. You must have captured all 120 moths to unlock the purchase. \n4. Note: Finding all 120 also rewards the 'Dust 'Em Off' achievement (Title: Dustlord).",
   ["author"] = "AI",
   ["difficulty"] = 3,
   ["category"] = 1,
   ["expansion"] = 11,
},
{
   ["mountID"] = 2915,
    ["name"] = "Unbound Manawyrm",
    ["tips"] = "Unbound Manawyrm. \n\n1. Source: Vendor Sergeant Vornin, Silvermoon City. \n2. Requirement: Complete the 'Void Response Team' achievement, then purchase the mount for 200 Field Accolades. \n3. Note: Void Response Team is a substantial checklist covering both Eversong Woods and Zul'Aman. You need to complete 25 Void Assaults, kill 100 corrupted creatures, and earn 100 Field Accolades as part of the achievement requirements. Sergeant Vornin is found at /way #2393 48.6 50.6. The Assault portion follows the weekly zone rotation, so this is not something you can necessarily brute-force in one sitting.",
    ["author"] = "AI",
    ["difficulty"] = 4,
    ["category"] = 1,
    ["expansion"] = 11,
},
{
   ["mountID"] = 3033,
    ["name"] = "Tortured Gorger",
    ["tips"] = "Tortured Gorger. \n\n1. Source: Vendor Kifaan in Val or Naigtal. \n2. Requirement: Complete the 'Heroic Showdowns' achievement, then purchase the mount for 15 Voidlight Marl. \n3. Note: Heroic Showdowns is a meta-achievement requiring six Heroic World Tier achievements across Val and Naigtal. Among other things, you need to defeat 15 rare creatures, complete the relevant zone objectives, and deal with the Heroic versions of the Showdown content. This is substantially easier with a group, especially when working through the rare-kill objectives. Kifaan can be found at both Showdown base camps.",
    ["author"] = "AI",
    ["difficulty"] = 4,
    ["category"] = 1,
    ["expansion"] = 11,
},
{
   ["mountID"] = 2990,
    ["name"] = "Netherforged Nullframe",
    ["tips"] = "Netherforged Nullframe. \n\n1. Source: Vendor Kifaan in Val/Naigtal. \n2. Requirement: Complete the 'A Trip Through the Stars' achievement, then purchase the mount for 15 Voidlight Marl. \n3. Note: A Trip Through the Stars is the Naigtal meta-achievement and requires six achievements covering the Naigtal Showdown content, including the introduction and follow-up questlines, rare kills, Climate Strange, and Showdown Success. The achievement is time-gated by the Naigtal activity rotation; players report that completing the required progression takes 3 trips through Naigtal, or roughly 6 weeks. Don't confuse it with A Trip Around the Stars, which unlocks the Voidmancer's Starcarver instead.",
    ["author"] = "AI",
    ["difficulty"] = 4,
    ["category"] = 1,
    ["expansion"] = 11,
},
{
   ["mountID"] = 2988,
    ["name"] = "Voidmancer's Starcarver",
    ["tips"] = "Voidmancer's Starcarver. \n\n1. Source: Vendor Kifaan in Val/Naigtal. \n2. Requirement: Complete the 'A Trip Around the Stars' achievement, then purchase the mount for 15 Voidlight Marl. \n3. Note: A Trip Around the Stars is the Val meta-achievement. It requires six achievements covering the Val introduction and follow-up questlines, Val rare creatures, Climate Strange: Val, and Showdown Success: Val. Unlike the Naigtal counterpart, this achievement is specifically tied to Val. Make sure you complete A Trip Around the Stars, not A Trip Through the Stars; the latter unlocks the Netherforged Nullframe.",
    ["author"] = "AI",
    ["difficulty"] = 4,
    ["category"] = 1,
    ["expansion"] = 11,
},
{
   ["mountID"] = 3020,
   ["name"] = "Caustic Venomfang",
   ["tips"] = "Caustic Venomfang. \n\n1. Source: Vendor Skull of Er'inye in the Vaults of Atal'Utek. \n2. Method: Purchase the mount for 10,000 Corrosive Coins. Skull of Er'inye is located next to the Altar of Corrosion at /way #2509 51.2 62.4. \n3. Note: Corrosive Coins are earned throughout the Vaults of Atal'Utek by participating in the area's venom-related activities. The weekly 'Purging the Vaults' quest is a useful chunk of currency, while Temple Patrols, Temple Strikes, and Temple Incursions are the core repeatable activities. Unlocking the Corrosive Spirit upgrades increases your coin income, so work on those upgrades instead of treating the 10,000 coins as a pure flat grind.",
   ["author"] = "AI",
   ["difficulty"] = 3,
   ["category"] = 1, -- Vendor
   ["expansion"] = 11, -- Midnight
},
{
   ["mountID"] = 3032,
   ["name"] = "Preyhunter's Fury",
   ["tips"] = "Preyhunter's Fury. \n\n1. Source: Vendor Construct V'anore in Astalor's Sanctum, Silvermoon City. \n2. Requirement: Reach Preyhunter's Journey Rank 10, then purchase the mount for 2,250 Remnant of Anguish. \n3. Note: Preyhunter's Journey is progressed by completing Prey Hunts. Under the normal Season 2 progression, the first 4 Hunts each week award 1,000 Journey, for 4,000 total (one full rank). Hunts beyond the first 4 only award 50 Journey. Patch 12.1.5 also adds catch-up bonuses: below Rank 3, Hunts award 4,000 Journey each; from Rank 3 through Rank 8, the first 4 Hunts of the week award 2,000 each. Save your Remnant of Anguish rather than spending it on the other Prey rewards if the mount is your goal. Construct V'anore is at /way #2393 55.7 65.8.",
   ["author"] = "AI",
   ["difficulty"] = 4,
   ["category"] = 1, -- Vendor
   ["expansion"] = 11, -- Midnight
},
{
   ["mountID"] = 3043,
   ["name"] = "Corroded Soul Crusher",
   ["tips"] = "Corroded Soul Crusher. \n\n1. Source: Vendor Telemancer Astrandis at the Delver's Headquarters in Silvermoon City. \n2. Requirement: Reach Rank 5 in the Midnight Season 2 Delver's Journey, then purchase the mount for 10 Voidlight Marl. \n3. Note: This is a guaranteed vendor purchase—there is no drop chance. Delver's Journey progress comes from completing Delves and related Delve activities, so simply keep running Midnight Delves while working toward Rank 5. The mount becomes available from Telemancer Astrandis as soon as the Rank 5 milestone is reached. Delver's Headquarters is at /way #2393 52.4 78.2.",
