{
   ["mountID"] = 2965,
    ["name"] = "Void-Corrupted Lynx",
    ["tips"] = "Void-Corrupted Lynx. \n\n1. Source: Leatherworking - crafted with 'Rope Lynx Harness'. \n2. Method: Reach Ritual Sites Renown Rank 8 to unlock the chance for the required materials to drop. The Pattern: Rope Lynx Harness can drop from the final chest of Ritual Sites, while the Broken Lynx Leash can drop from the final chest at any Ritual Site difficulty. Crafting the mount requires 1 Broken Lynx Leash, 40 Mote of Primal Energy, 1 Infused Scalewoven Hide, and 2 Sin'dorei Armor Banding. \n3. Note: The Pattern: Rope Lynx Harness appears to have its best/known drop rate from Tier 5 Ritual Sites with 8 challenges, while the Broken Lynx Leash can drop from any tier once Rank 8 Renown is reached. The pattern is Bind on Equip and can therefore be bought from the Auction House, but the Broken Lynx Leash is Bind on Pickup. If you are not a Leatherworker, you can get the mount crafted through a public or personal crafting order once you have the leash. Farming higher Ritual Site tiers and more challenges gives more spoils/renown, so use the highest difficulty you can complete efficiently.",
