    ["name"] = "Void-Corrupted Hex Eagle",
    ["tips"] = "Void-Corrupted Hex Eagle\n\n1. Source: Drop from Void-Corrupted Hex Eagle\n2. Requirement: Zul'Aman Ritual Site, the Broken Throne, tier 2 or above\n3. Method: Pick up Misplaced Ritual Candle [button=\"/way #2585 51.5 47.8 Misplaced Ritual Candle\"] place the missing candle in the northeast corner of the ritual circle at [button=\"/way #2585 50.75 47.16 Missing Candle\"]. Click the middle candle to summon Void-Corrupted Hex Eagle which will drop the mount\n4. Note: If you do not bring the candles first, you will instead spawn 3 smaller Eaglets when pressing the middle candle.",
