{
    ["mountID"] = 2964,
    ["name"] = "Void-Touched Snapdragon",
    ["tips"] = "Void-Touched Snapdragon\n\n1. Source: Kill the rare spawn Void-Touched Snapdragon\n2. Method: To spawn the rare, interact with Washed Up Kelp in Daggerspine Point Ritual Site. There is always 2 Kelp spawning pr run and the spawn chance of the rare is rather low\n3. Note: Use Starry-Eyed Goggles to make it easier to spot the kelp, and bring a water-walking mount\n[button=\"/way #2594 46 45 Kelp 1; /way #2594 61 77 Kelp 2; /way #2594 47 72 Kelp 3; /way #2594 66 74 Kelp 4; /way #2594 41 73 Kelp 5; /way #2594 38 64 Kelp 6; /way #2594 50 55 Kelp 7; /way #2594 53 55 Kelp 8\"]",
