    ["mountID"] = 2779,
    ["name"] = "Witherbark Warbear Mother",
    ["tips"] = "Witherbark Warbear Mother\n\n1. Source: Broken Throne (Tier 2+).\n2. Method: Buy 6x Practically Pork. Find Chubs (stealthed under a tree [button=\"/way #2585 55.81 49.52 Chubs\"]) and feed him 1x Pork to collect him. Go to Chewed Meat[button=\"/way #2585 56.0 38.5 Chewed Meat\"], summon the Chubs pet, and defeat the Angry Amani Warbear that spawns. Lastly Feed the friendly Warbear 5x Pork.\n3. Note: Yields the Witherbark Warbear Harness directly into your inventory. ",
